// Des: Sends each SQL statement to all database vendors
// Flo: statements stay in one neutral form > saved in a local spool per mirror > main vendor and mirrors run in parallel > success clears the spool, failure keeps it and skips that mirror for the run > backfill rebuilds a new mirror from local tables in chunks
// I/O: SQL calls (main vendor + mirrors, Db) > the same SQL calls; only the main vendor's answer decides success; a mirror catches up from its spool, so nothing is lost and order is kept
// ===================================================================
const std = @import("std"); const sqlz = @import("sy-clou-sqlz.zig"); const sqli = @import("st-stor-sqli.zig"); const cfgz = @import("cf-conf-load.zig"); const fail = @import("ru-fail-over.zig"); const sync = @import("sy-clou-sync.zig"); const mirr = @import("sy-mirr-stor.zig"); const xlat = @import("sy-mirr-xlat.zig");
const CF = .{ .ddlz = "CREATE TABLE IF NOT EXISTS", .done = "msql_", .phas = "mbkp_", .offz = "mbko_" };
pub const Smem = struct { name: []const u8, sql2: sqlz.Sqlz, idxz: usize };
pub const Sanz = struct { dbzz: *sqli.Dbzz, iozz: std.Io, nowz: i64, conf: cfgz.Conf, prim: Smem, mirs: []const Smem, stat: *mirr.Dead, ddlz: []bool, sent: u32 = 0, drps: std.ArrayList([]const u8) = .empty };
const Qjob = struct { sql2: sqlz.Sqlz, iozz: std.Io, stms: []const []const u8, errz: ?anyerror = null, arnz: std.heap.ArenaAllocator };
fn qjobRunz(jobz: *Qjob) void { const allo = jobz.arnz.allocator(); jobz.sql2.exec(jobz.sql2.ctx2, allo, jobz.iozz, jobz.stms) catch |err3| { jobz.errz = err3; }; }
fn ddlzOnlz(stms: []const []const u8) bool { for (stms) |item| { if (!std.mem.startsWith(u8, item, CF.ddlz)) return false; } return stms.len > 0; }
fn flagName(aren: std.mem.Allocator, pref: []const u8, name: []const u8) ![]const u8 { return std.fmt.allocPrint(aren, "{s}{s}", .{ pref, name }); }
fn spooAddz(self: *Sanz, mem: Smem, stms: []const []const u8) !void { try self.dbzz.exec("SAVEPOINT mspl;"); errdefer self.dbzz.exec("ROLLBACK TO mspl; RELEASE mspl;") catch {}; for (stms) |item| { var stmt = try self.dbzz.prep("INSERT INTO mspl(vend,stmt) VALUES(?1,?2);"); defer stmt.fini(); try stmt.bindText(1, mem.name); try stmt.bindText(2, item); _ = try stmt.step(); } try self.dbzz.exec("RELEASE mspl;"); }
fn capzChek(self: *Sanz, aren: std.mem.Allocator, mem: Smem) !void { var cntz = try self.dbzz.prep("SELECT count(*) FROM mspl WHERE vend=?1;"); defer cntz.fini(); try cntz.bindText(1, mem.name); _ = try cntz.step(); if (cntz.colzIntz(0) <= self.conf.clou_mirr_spoo_maxz) return; var del2 = try self.dbzz.prep("DELETE FROM mspl WHERE vend=?1;"); defer del2.fini(); try del2.bindText(1, mem.name); _ = try del2.step(); for ([_][]const u8{ CF.done, CF.phas, CF.offz }) |pref| try fail.flagSetz(self.dbzz, try flagName(aren, pref, mem.name), 0); try self.drps.append(aren, mem.name); }
const Batz = struct { stms: []const []const u8, lasz: i64, dflg: bool };
fn batzOfzz(self: *Sanz, aren: std.mem.Allocator, mem: Smem) !?Batz { var stmt = try self.dbzz.prep("SELECT seqz,stmt FROM mspl WHERE vend=?1 ORDER BY seqz LIMIT ?2;"); defer stmt.fini(); try stmt.bindText(1, mem.name); try stmt.bindIntz(2, self.conf.clou_mirr_batz); var list: std.ArrayList([]const u8) = .empty; var lasz: i64 = 0; const dflg = !self.ddlz[mem.idxz]; if (dflg) { for (sqlz.DDL) |item| try list.append(aren, item); } const base = list.items.len; while (try stmt.step()) { lasz = stmt.colzIntz(0); try list.append(aren, try aren.dupe(u8, stmt.colzText(1))); } if (list.items.len == base) return null; return .{ .stms = try xlat.listDial(aren, mem.sql2.dial, list.items), .lasz = lasz, .dflg = dflg }; }
fn clrzSpoo(self: *Sanz, name: []const u8, lasz: i64) !void { var stmt = try self.dbzz.prep("DELETE FROM mspl WHERE vend=?1 AND seqz<=?2;"); defer stmt.fini(); try stmt.bindText(1, name); try stmt.bindIntz(2, lasz); _ = try stmt.step(); }
fn ship(self: *Sanz, aren: std.mem.Allocator, prim: ?[]const []const u8) !void { var jobs: std.ArrayList(Qjob) = .empty; var owns: std.ArrayList(usize) = .empty; var lass: std.ArrayList(i64) = .empty; var wits: std.ArrayList(bool) = .empty; const isdd = if (prim) |stms| ddlzOnlz(stms) else false; if (prim) |stms| try jobs.append(aren, .{ .sql2 = self.prim.sql2, .iozz = self.iozz, .stms = try xlat.listDial(aren, self.prim.sql2.dial, stms), .arnz = mirr.arenNewz() }); const offz: usize = jobs.items.len; for (self.mirs, 0..) |mem, indx| { if (self.stat.dead[mem.idxz]) continue; if (isdd) { if (self.ddlz[mem.idxz]) continue; try jobs.append(aren, .{ .sql2 = mem.sql2, .iozz = self.iozz, .stms = try xlat.listDial(aren, mem.sql2.dial, prim.?), .arnz = mirr.arenNewz() }); try lass.append(aren, 0); try wits.append(aren, true); } else { const batz = (try batzOfzz(self, aren, mem)) orelse continue; try jobs.append(aren, .{ .sql2 = mem.sql2, .iozz = self.iozz, .stms = batz.stms, .arnz = mirr.arenNewz() }); try lass.append(aren, batz.lasz); try wits.append(aren, batz.dflg); } try owns.append(aren, indx); } mirr.runzAllz(Qjob, qjobRunz, jobs.items); defer for (jobs.items) |*jobz| jobz.arnz.deinit(); for (jobs.items[offz..], owns.items, lass.items, wits.items) |jobz, indx, lasz, dflg| { const mem = self.mirs[indx]; if (jobz.errz) |err3| { self.stat.dead[mem.idxz] = true; self.stat.errz[mem.idxz] = err3; continue; } self.stat.used[mem.idxz] = true; self.sent += @intCast(jobz.stms.len); if (dflg) self.ddlz[mem.idxz] = true; if (!isdd) try clrzSpoo(self, mem.name, lasz); } if (offz == 1) { if (jobs.items[0].errz) |err3| return err3; } }
fn exe3(ctx2: *anyopaque, aren: std.mem.Allocator, _: std.Io, stm2: []const []const u8) anyerror!void { const self: *Sanz = @ptrCast(@alignCast(ctx2)); if (stm2.len == 0) return; if (!ddlzOnlz(stm2)) { for (self.mirs) |mem| try spooAddz(self, mem, stm2); } const rslz = ship(self, aren, stm2); for (self.mirs) |mem| try capzChek(self, aren, mem); return rslz; }
pub fn sanzSqlz(self: *Sanz) sqlz.Sqlz { return .{ .ctx2 = self, .dial = .sqlt, .exec = exe3 }; }
pub fn sanzLeft(self: *Sanz) !i64 { var stmt = try self.dbzz.prep("SELECT count(*) FROM mspl;"); defer stmt.fini(); _ = try stmt.step(); return stmt.colzIntz(0); }
pub fn sanzDrai(self: *Sanz, aren: std.mem.Allocator) !void { try ship(self, aren, null); }
fn rowsChun(self: *Sanz, aren: std.mem.Allocator, synz: *sync.Sync, phas: i64, offz: i64, list: *std.ArrayList([]const u8)) !u32 { const sqls = [_][:0]const u8{ "SELECT urlz FROM page ORDER BY urlz LIMIT ?1 OFFSET ?2;", "SELECT hexz,packk,offs,lenz FROM pack ORDER BY hexz LIMIT ?1 OFFSET ?2;", "SELECT packz,timz,ents FROM purg ORDER BY packz LIMIT ?1 OFFSET ?2;" }; var stmt = try self.dbzz.prep(sqls[@intCast(phas)]); defer stmt.fini(); try stmt.bindIntz(1, self.conf.clou_mirr_batz); try stmt.bindIntz(2, offz); var cont: u32 = 0; const dial: sqlz.Dial = .sqlt; while (try stmt.step()) { cont += 1; if (phas == 0) { const urlz = try aren.dupe(u8, stmt.colzText(0)); if (try sync.goneSkip(synz, aren, urlz, self.nowz)) continue; _ = try sync.reczStmt(synz, aren, urlz, list); } else if (phas == 1) { const cols = [_]sqlz.Colz{ .{ .name = "hexz", .valu = try sqlz.litz(aren, dial, stmt.colzText(0)) }, .{ .name = "pack", .valu = try sqlz.litz(aren, dial, stmt.colzText(1)) }, .{ .name = "offs", .valu = try std.fmt.allocPrint(aren, "{d}", .{stmt.colzIntz(2)}) }, .{ .name = "lenz", .valu = try std.fmt.allocPrint(aren, "{d}", .{stmt.colzIntz(3)}) } }; try list.append(aren, try sqlz.upse(aren, dial, "cl_manif", "hexz", &cols)); } else { const cols = [_]sqlz.Colz{ .{ .name = "packz", .valu = try sqlz.litz(aren, dial, stmt.colzText(0)) }, .{ .name = "timz", .valu = try std.fmt.allocPrint(aren, "{d}", .{stmt.colzIntz(1)}) }, .{ .name = "ents", .valu = try std.fmt.allocPrint(aren, "{d}", .{stmt.colzIntz(2)}) } }; try list.append(aren, try sqlz.upse(aren, dial, "cl_purg", "packz", &cols)); } } return cont; }
pub fn sanzBack(self: *Sanz, aren: std.mem.Allocator, synz: *sync.Sync) !u32 { var tota: u32 = 0; for (self.mirs) |mem| { const kdon = try flagName(aren, CF.done, mem.name); if (try fail.flagGetz(self.dbzz, kdon) == 1) continue; const kpha = try flagName(aren, CF.phas, mem.name); const koff = try flagName(aren, CF.offz, mem.name); var phas = try fail.flagGetz(self.dbzz, kpha); var offz = try fail.flagGetz(self.dbzz, koff); var gotz: u32 = 0; var donz = false; while (gotz < self.conf.clou_mirr_batz and !donz) { var list: std.ArrayList([]const u8) = .empty; const cont = try rowsChun(self, aren, synz, phas, offz, &list); if (list.items.len > 0) try spooAddz(self, mem, list.items); gotz += @intCast(list.items.len); if (cont < self.conf.clou_mirr_batz) { phas += 1; offz = 0; } else offz += self.conf.clou_mirr_batz; if (phas > 2) { donz = true; phas = 0; } } if (donz) try fail.flagSetz(self.dbzz, kdon, 1); try fail.flagSetz(self.dbzz, kpha, phas); try fail.flagSetz(self.dbzz, koff, offz); tota += gotz; } return tota; }
